async def _current_unit_cost(
    session: AsyncSession,
    tenant_id: uuid.UUID,
    item: Item,
    warehouse_id: uuid.UUID,
    qty: Decimal,
    method: CostingMethod,
) -> Decimal:
    """The current per-unit cost of an (item, warehouse) for a value-neutral transfer's ledger entry:
    the moving-average avg, or the FIFO weighted average of the live layers. Reads only (no writes)."""
    if method == CostingMethod.MOVING_AVERAGE:
        valuation = await _locked_valuation(session, tenant_id, item.id, warehouse_id)
        return Decimal(valuation.avg_unit_cost) if valuation is not None else Decimal(0)
    # FIFO: weighted average of the live layers' value over their remaining quantity (informational
    # for a within-warehouse transfer's ledger row; no value moves).
    row = (
        await session.execute(
            select(
                func.sum(CostLayer.remaining_qty),
                func.sum(CostLayer.remaining_qty * CostLayer.unit_cost),
            ).where(
                CostLayer.tenant_id == tenant_id,
                CostLayer.item_id == item.id,
                CostLayer.warehouse_id == warehouse_id,
                CostLayer.remaining_qty > 0,
            )
        )
    ).first()
    total_qty = Decimal(row[0]) if row is not None and row[0] is not None else Decimal(0)
    total_value = Decimal(row[1]) if row is not None and row[1] is not None else Decimal(0)
    return (total_value / total_qty) if total_qty > 0 else Decimal(0)

